// Извлекаем параметры поиска
const input = $input.first().json;

const userId = input.user_id || input.body?.user_id;
const category = input.category || input.body?.category;
const moq = input.moq || input.body?.moq || 'any';
const priceRange = input.price_range || input.body?.price_range || 'any';

console.log('Received search request:', { userId, category, moq, priceRange });

return {
  json: {
    user_id: userId,
    category: category,
    moq: moq,
    price_range: priceRange,
    timestamp: new Date().toISOString()
  }
};

