// Парсим AI ответ из JSON
const item = $input.first().json;
let aiData = {};

try {
  // Извлекаем JSON из ответа AI
  let aiResponse = item.ai_output || '{}';

  // Если это уже объект
  if (typeof aiResponse === 'object') {
    aiData = aiResponse;
  } else {
    // Убираем markdown блоки если есть
    aiResponse = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    // Парсим JSON
    aiData = JSON.parse(aiResponse);
  }

  console.log('Parsed AI data:', aiData);
} catch (error) {
  console.error('Error parsing AI response:', error.message);
  // Дефолтные значения если парсинг не удался
  aiData = {
    reliability_score: 5,
    recommended: false,
    summary_ru: 'Не удалось проанализировать компанию',
    pros: ['Требуется дополнительный анализ'],
    risks: ['Недостаточно данных']
  };
}

return {
  json: {
    timestamp: item.timestamp,
    company_name: item.company_name,
    rating: item.rating,
    moq: item.moq,
    price: item.price,
    location: item.location,
    years: item.years,
    email: item.email,
    url: item.url,
    verified: item.verified,
    ai_score: aiData.reliability_score || 5,
    recommended: aiData.recommended || false,
    summary: aiData.summary_ru || 'Нет данных',
    pros: Array.isArray(aiData.pros) ? aiData.pros.join(', ') : 'Нет данных',
    risks: Array.isArray(aiData.risks) ? aiData.risks.join(', ') : 'Нет данных'
  }
};

// Собираем все результаты
const items = $input.all();

const leads = items.map(item => item.json);

// Сортируем по AI score
leads.sort((a, b) => b.ai_score - a.ai_score);

console.log(`Returning ${leads.length} analyzed leads`);

return {
  json: {
    success: true,
    total_leads: leads.length,
    timestamp: new Date().toISOString(),
    leads: leads
  }
};
